insert into public.sunprime_content_singletons (key, data) values ('site', $sunp${"name":"Sunprime Energy Solutions","shortName":"Sunprime Energy Solutions","url":"https://sunpesolutions.com","legalName":"Sunprime Energy Solutions Pvt. Ltd.","tagline":"Engineered solar for industry, infrastructure, and institutions.","description":"Sunprime Energy Solutions is a Delhi-based solar EPC company designing, engineering, building, and operating grid-tied rooftop and ground-mount solar PV plants for commercial, industrial, and institutional clients across India. ISO 9001:2015 certified. 15,000+ kWp delivered.","heroImage":"/photos/hero-industrial-rooftop.jpg","contact":{"address":"602, Devika Tower, Nehru Place, New Delhi 110019, India","addressLine1":"602, Devika Tower","addressLine2":"Nehru Place","locality":"New Delhi","region":"Delhi","postalCode":"110019","country":"IN","email":"md@sunpesolutions.com","gmail":"sunprime.energysol@gmail.com","phone":"+91 98181 00758","phoneHref":"tel:+919818100758","hours":"Mon–Sat, 10:00–18:30 IST"},"social":{"linkedin":"https://www.linkedin.com/company/sunprime-energy-solutions","facebook":"https://www.facebook.com/sunprimeenergysolutions","instagram":"https://www.instagram.com/sunprimeenergysolutions"},"nav":[{"label":"Home","href":"/"},{"label":"About Us","href":"/about"},{"label":"Services & Projects","href":"/services"},{"label":"Why Solar?","href":"/why-solar"},{"label":"Blog","href":"/blog"},{"label":"Enquiry & Career","href":"/careers"},{"label":"Contact","href":"/contact"}],"stats":[{"value":"15,000+","label":"kWp delivered"},{"value":"ISO 9001","label":"Quality certified"},{"value":"In-house","label":"Design, EPC & O&M"},{"value":"Pan-India","label":"Project footprint"}],"certifications":[{"code":"ISO 9001:2015","body":"Quality Management System"},{"code":"MSME Registered","body":"Ministry of Micro, Small & Medium Enterprises"}],"partners":["Havells","SolarEdge","Delta Electronics","REC Solar","Amplus","Jackson","YouSolar","Solar-Log"],"partnerStack":[{"category":"Modules","partners":["REC Solar","Rhine Solar"]},{"category":"Inverters & power conversion","partners":["SolarEdge","Delta Electronics"]},{"category":"BoS & switchgear","partners":["Havells"]},{"category":"Monitoring & analytics","partners":["Solar-Log"]},{"category":"Channel partnerships","partners":["Amplus","Jackson","YouSolar"]}],"services":[{"slug":"rooftop-solar","no":"01","title":"Commercial & Industrial Rooftop Solar","summary":"Grid-tied and hybrid solar PV systems engineered for commercial, industrial, and institutional rooftops across India — designed around long-term yield, not lowest BOM.","bullets":["Structural & shadow analysis","Net-metering compliant designs","Tier-1 modules and inverters"]},{"slug":"epc","no":"02","title":"Solar EPC & Turnkey Execution","summary":"End-to-end solar engineering, procurement, and construction — civil works, mounting structures, DC/AC electricals, and commissioning under a single accountable team.","bullets":["In-house design & MEP","DGS&D-grade BOQ","Single-window project ownership"]},{"slug":"om","no":"03","title":"Solar Operations & Maintenance","summary":"Performance-monitored solar O&M with remote analytics, PR reporting, and predictable SLAs — protecting plant yield across its 25-year service life.","bullets":["Remote monitoring & alerts","PR-based performance SLAs","Preventive & corrective AMC"]},{"slug":"advisory","no":"04","title":"Solar Advisory, Subsidy & Compliance","summary":"Subsidy facilitation, DISCOM net-metering, statutory clearances, and feasibility studies — engineered off your project's critical path so commissioning stays on schedule.","bullets":["State & central subsidy support","DISCOM & net-metering","Regulatory & statutory filings"]}],"industries":[{"slug":"manufacturing","title":"Manufacturing & Industrial","body":"Large rooftop or ground-mount plants for plants, factories, and process facilities — sized to flatten Tariff Schedule peaks.","img":"/photos/hero-industrial-rooftop.jpg"},{"slug":"education","title":"Education & Institutions","body":"Schools, colleges, and universities — campus-wide rooftop systems delivering 20+ years of reduced operating costs.","img":"/photos/rooftop-commercial.jpg"},{"slug":"healthcare","title":"Healthcare & Hospitals","body":"Hospital blocks, diagnostic centres, and pharma cold-storage — engineered for redundancy and uninterrupted operations.","img":"/photos/rooftop-foothill.jpg"},{"slug":"hospitality","title":"Commercial, Hospitality & Retail","body":"Hotels, resorts, and large retail formats — solar with O&M tied to your asset's 24×7 brand standards.","img":"/photos/rooftop-urban.jpg"},{"slug":"warehousing","title":"Warehousing & Logistics","body":"Logistics parks, cold-chain, and distribution centres — large rooftop arrays utilised across long roof spans.","img":"/photos/aerial-ground-mount.jpg"},{"slug":"agri","title":"Agriculture & Agrivoltaic","body":"Solar carports, agrivoltaic canopies, and dairy structures — dual-use sites that earn from energy and produce.","img":"/photos/agrivoltaic-canopy.jpg"}],"homeFaqs":[{"q":"What does a rooftop solar EPC project cost in India?","a":"Prices vary with roof type, structural readiness, BOM choices, and applicable subsidies. Sunprime Energy Solutions issues a fixed-price BOQ after the site survey — a firm number for your site, with no surprise variations during execution."},{"q":"Which OEMs do you specify in your BOM?","a":"We work with Tier-1 ALMM approved module manufacturers. Every BOM names OEM and model — no generic placeholders."},{"q":"Do you operate solar plants you didn't build?","a":"Yes. Our Solar O&M practice onboards existing rooftop and ground-mount plants — whether built by another EPC or an in-house team — and runs them under PR-based SLAs with remote monitoring."},{"q":"Where in India do you take on projects?","a":"Across India. From our Delhi office, we deliver commercial, industrial, and institutional solar projects nationwide."}],"serviceAreas":["Delhi NCR","Haryana","Punjab","Uttar Pradesh","Rajasthan","Himachal Pradesh","Madhya Pradesh","Gujarat","Maharashtra","Uttarakhand"],"differentiators":[{"title":"Engineering-led, not sales-led","body":"Every proposal is grounded in a site survey, structural review, and yield model — not a price-per-watt formula."},{"title":"Tier-1 component partnerships","body":"Direct relationships with Goodwe, Havells, Sungrow, Renewsys, Adani, Vikram, and Waaree mean component access, warranty alignment, and bankable BOM."},{"title":"Single team, single accountability","body":"Design, EPC, and O&M sit inside Sunprime Energy Solutions, under one accountable team."},{"title":"Compliance handled, not delegated","body":"In-house regulatory experience keeps DISCOM and statutory filings off your critical path."}],"process":[{"step":"01","title":"Site assessment","body":"Survey, shadow study, structural and load review."},{"step":"02","title":"Engineering & design","body":"Yield model, single-line diagrams, BOQ."},{"step":"03","title":"Approvals","body":"DISCOM filings, net-metering, CEIG/CEA clearances."},{"step":"04","title":"Subsidy","body":"Subsidy assessment, applications, and disbursement support."},{"step":"05","title":"Procurement","body":"Tier-1 modules, inverters, BoS — direct from OEM."},{"step":"06","title":"EPC & commissioning","body":"Civil, structures, DC/AC, testing, handover."},{"step":"07","title":"O&M & monitoring","body":"PR-based SLA, remote analytics, AMC."}],"projects":[{"title":"Manufacturing facility","location":"Rajasthan","capacity":"1,000 kWp","type":"Industrial rooftop · CAPEX","img":"/photos/hero-industrial-rooftop.jpg"},{"title":"Manufacturing unit","location":"Rajasthan","capacity":"632.4 kWp","type":"Industrial rooftop · CAPEX","img":"/photos/aerial-ground-mount.jpg"},{"title":"Educational institution","location":"New Delhi","capacity":"300 kWp","type":"Institutional rooftop · RESCO","img":"/photos/rooftop-commercial.jpg"}],"testimonial":{"quote":"Sunprime Energy Solutions treated our plant the way our own engineering team would. The yield modelling was honest, the BOQ held up, and commissioning came in on the date they committed in month one.","name":"Operations Director","company":"Manufacturing client, NCR"},"serviceDetails":[{"slug":"rooftop-solar","no":"01","title":"Rooftop Solar","lead":"Grid-tied and hybrid PV systems engineered for commercial, industrial, and institutional rooftops — sized for yield, structured for the next twenty-five summers.","includes":["Site survey, structural & shadow analysis","Yield modelling (PVsyst-grade) and ROI","Net-metering compliant single-line designs","Tier-1 modules, string and central inverters","Mounting structures rated for site wind zone","DC/AC cabling, LT panels, monitoring","Engineering, procurement & construction, including BOS"],"suited":"Manufacturing units, warehousing, schools and universities, hospitals, hotels, large commercial complexes.","typical":"100 kWp – 1.5 MWp","timeline":"8–14 weeks from PO","img":"/photos/rooftop-commercial.jpg"},{"slug":"epc","no":"02","title":"EPC & Turnkey Execution","lead":"Full engineering, procurement, and construction under a single accountable team — civil works, structures, electricals, and commissioning, on a fixed schedule.","includes":["Detailed engineering & design","Procurement from Tier-1 OEMs","Civil & foundation works","Mounting and module installation","DC/AC works and testing","Commissioning and handover"],"suited":"Clients building utility-scale or campus-scale assets who want a single accountable contractor from groundbreak to PR sign-off.","typical":"500 kWp – multi-MW","timeline":"16–28 weeks","img":"/photos/aerial-utility-farm.jpg"},{"slug":"om","no":"03","title":"Operations & Maintenance","lead":"Performance-monitored O&M with remote analytics and predictable SLAs — protecting plant yield across its 25-year service life.","includes":["24×7 remote monitoring","Performance Ratio (PR) reporting","Preventive maintenance schedule","Module cleaning programme","Corrective AMC with response SLAs","Annual yield & insurance reports"],"suited":"Existing solar assets — whether built by Sunprime Energy Solutions or transitioned in from another EPC — that need professional, accountable operations.","typical":"Any plant ≥ 50 kWp","timeline":"Onboarding in 2 weeks","img":"/photos/rooftop-urban.jpg"},{"slug":"advisory","no":"04","title":"Advisory & Compliance","lead":"Subsidy facilitation, net-metering, and statutory clearances — kept off your project's critical path so commissioning stays on schedule.","includes":["State & central subsidy applications","DISCOM net-metering filings","CEIG/CEA approvals","Energy audits & feasibility","Capex/Opex model evaluation","Independent owner's engineer reviews"],"suited":"Asset owners, CFO offices, and project teams who need an independent perspective before issuing PO.","typical":"Per engagement","timeline":"2–8 weeks","img":"/photos/rooftop-foothill.jpg"}],"principles":[{"no":"01","title":"Yield over price-per-watt","body":"Bankable plants outlive cheap ones. We optimise for 25-year energy output."},{"no":"02","title":"Engineering signs off, not sales","body":"Every design decision is owned by the engineer responsible for the plant after handover."},{"no":"03","title":"Tier-1 BOM, no exceptions","body":"Modules, inverters, and BoS are sourced from manufacturers we can support across the warranty term."},{"no":"04","title":"Single-team accountability","body":"Design, EPC, and O&M sit inside Sunprime Energy Solutions, under one accountable team."}],"founder":{"eyebrow":"Our founder","title":"The story of our founder","name":"Lt. Mr. S.K. Saini","role":"Founder, Visionary Leader & Industry Pioneer","story":["Late Mr. S.K. Saini, a distinguished Chartered Accountant and seasoned management professional, founded Sunprime Energy Solutions Pvt. Ltd. with a vision to transform the energy landscape through sustainable, customer-centric, and innovative solutions — providing Energy Management Services focused on solar plant installations, energy audits & ESCO projects, EV infrastructure, and CSR consultancy.","With over 35 years of exemplary service in the Tata Group — including impactful tenures at Tata Steel and Tata Power Delhi Distribution Ltd. — Mr. Saini brought a wealth of experience, leadership, and purpose to the company he established. His pioneering work in power distribution, particularly in reducing Aggregate Technical & Commercial (AT&C) losses from 53% to 7%, and leading major technology transformations like the SAP-ISU implementation, garnered international acclaim. He was passionate about using innovation not only to drive business performance but also to uplift underserved communities, earning recognition from institutions such as Harvard, the World Bank, and the Confederation of Indian Industry.","As the driving force behind social innovation and renewable energy adoption, he laid the foundation for Sunprime's mission — to promote clean energy, combat climate change, drive digitization, and deliver impactful CSR initiatives.","His legacy of excellence, compassion, and vision continues to guide the company's direction and values. Though he is no longer with us, Mr. Saini's enduring spirit remains the cornerstone of our identity and purpose."],"competencies":["15 years' experience in the power distribution sector (Tata Power Delhi) & 20 years in Tata Steel","Headed Commercial, Regulatory, BD, Solar, DSM & Energy Efficiency Initiatives and Social Innovation at Tata Power DDL as Sr. VP & Chief (Commercial, Business Services & Social Innovation)","Handled AT&C loss reduction from 53% to 7%","Process re-engineering — Program Director for SAP-ISU implementation","Rapport with almost all DISCOMs in the country","Executed rooftop solar projects of over 5 MWp in one and a half years as an entrepreneur","Strong connect with consumers in Delhi and NCR","Co-author of Winning the Hearts to Improve the Life of the Socially Deprived, released by the Hon'ble Vice President of India","Excellent relations with the International Solar Alliance (ISA) & member countries' High Commissions","Core member, Global Advisory Committee of the International Solar Alliance","Core member, Global Task Force of Foundations (ISA)","Strong connect with government departments for policy advocacy","Professionally, a Chartered Accountant","Founded Sunprime Energy Solutions Pvt. Ltd. in 2016 — an Energy Management Service company focused on Solar EPC, energy storage & O&M"]},"disciplines":[{"title":"Engineering","body":"Design, yield modelling, structural and electrical reviews. Every plant is engineered before it is sold."},{"title":"Project execution","body":"Procurement, civil, structures, electrical works, testing, and commissioning — in-house, on schedule."},{"title":"Operations & analytics","body":"24×7 monitoring, PR reporting, preventive and corrective maintenance, owner-side performance reviews."},{"title":"Compliance & advisory","body":"Subsidy pathways, DISCOM filings, statutory clearances, and independent feasibility studies."}],"expandedProjects":[{"title":"Manufacturing facility","location":"Rajasthan","capacity":"1,000 kWp","type":"Industrial rooftop","year":"CAPEX","img":"/photos/hero-industrial-rooftop.jpg"},{"title":"Manufacturing unit","location":"Rajasthan","capacity":"632.4 kWp","type":"Industrial rooftop","year":"CAPEX","img":"/photos/aerial-ground-mount.jpg"},{"title":"Educational institution","location":"New Delhi","capacity":"300 kWp","type":"Institutional rooftop","year":"RESCO","img":"/photos/rooftop-commercial.jpg"},{"title":"Commercial facility","location":"New Delhi","capacity":"100 kWp","type":"Commercial rooftop","year":"CAPEX","img":"/photos/rooftop-urban.jpg"},{"title":"Commercial complex","location":"New Delhi","capacity":"40 kWp","type":"Commercial rooftop","year":"CAPEX","img":"/photos/rooftop-foothill.jpg"},{"title":"Educational institution","location":"New Delhi","capacity":"25 kWp","type":"Institutional rooftop","year":"CAPEX","img":"/photos/agrivoltaic-canopy.jpg"}],"insights":[{"slug":"yield-vs-price-per-watt","title":"Yield over price-per-watt: why bankable plants outlive cheap ones","excerpt":"Why CFOs evaluating solar capex should weigh 25-year energy output, not month-one BOM savings.","category":"Engineering","readTime":"6 min read","img":"/photos/aerial-utility-farm.jpg"},{"slug":"net-metering-2024","title":"Net-metering after 2024: a compliance map for industrial buyers","excerpt":"What changed in DISCOM filings across major states, and what it means for your commissioning timeline.","category":"Policy","readTime":"9 min read","img":"/photos/rooftop-urban.jpg"},{"slug":"shadow-analysis","title":"Shadow analysis is engineering, not a checkbox","excerpt":"An honest yield model starts with a careful shadow study — not a generic per-kWp output assumption.","category":"Engineering","readTime":"7 min read","img":"/photos/rooftop-commercial.jpg"},{"slug":"om-pr-slas","title":"PR-based SLAs: how to write an O&M contract that actually pays","excerpt":"What to ask for, and what to refuse, in a 25-year O&M agreement.","category":"Operations","readTime":"8 min read","img":"/photos/rooftop-foothill.jpg"},{"slug":"tier-1-bom","title":"What 'Tier-1 BOM' actually means in 2024","excerpt":"Beyond Bloomberg's tier-1 list — what to verify on modules, inverters, and BoS before you sign.","category":"Procurement","readTime":"5 min read","img":"/photos/agrivoltaic-canopy.jpg"},{"slug":"feasibility-studies","title":"How to read a solar feasibility study (and what to push back on)","excerpt":"A short field guide for asset owners reading their first PVsyst report.","category":"Advisory","readTime":"10 min read","img":"/photos/aerial-ground-mount.jpg"}],"whySolar":{"reasons":[{"title":"Lower, predictable energy bills","body":"A grid-tied plant offsets a large share of your daytime load at a fixed, self-owned cost — insulating you from tariff hikes and demand-charge creep for the next twenty-five years."},{"title":"A capex that pays itself back","body":"Against a 25-year asset life, a well-engineered rooftop recovers its capex over its early years — after which it runs on effectively free energy. The exact payback varies with tariff, load, and financing model, so we model it for each site."},{"title":"Accelerated depreciation","body":"Indian tax law allows accelerated depreciation on solar assets, letting profit-making businesses write down a significant share of the investment in the first years of operation."},{"title":"A measurable ESG and CSR story","body":"Every kWp generated is auditable carbon avoided. Solar gives boards and CFOs a hard number for sustainability reporting — not a soft commitment."},{"title":"Low-maintenance, long-life asset","body":"With Tier-1 modules and disciplined O&M, a well-engineered plant degrades slowly and predictably — protected by 25–30 years performance warranties."},{"title":"Energy security on your own roof","body":"Self-generation reduces exposure to grid volatility and rising DISCOM tariffs, and pairs naturally with storage as your load profile evolves."}],"economics":[{"value":"3–5 yr","label":"Typical payback"},{"value":"25 yr+","label":"Asset service life"},{"value":"40%","label":"Accelerated depreciation, yr 1"},{"value":"₹0","label":"Fuel cost, generated kWh"}],"myths":[{"q":"Isn't solar only worth it with subsidy?","a":"No. For commercial and industrial sites the economics stand on tariff offset and depreciation alone. Subsidy, where applicable, simply shortens an already-attractive payback."},{"q":"How long will the plant last on my roof?","a":"Engineered for your site's wind zone, with Tier-1 modules and a disciplined O&M plan, a well-built plant is designed to perform for decades. Longevity comes down to a bankable BOM and consistent maintenance — both of which we own end to end."},{"q":"Does my roof need to be perfect?","a":"Most industrial and commercial roofs are viable. We run a structural and shadow study first, and design around what the roof actually is — not a generic per-kWp assumption."}]},"careers":{"email":"md@sunpesolutions.com","culture":[{"title":"Engineering signs off, not sales","body":"Decisions are owned by the people accountable for the plant after handover. If you'd rather be right than loud, you'll fit here."},{"title":"Real ownership, early","body":"Small, senior teams mean you carry a project end-to-end — not a sliver of it. Visibility and responsibility come quickly."},{"title":"Built to last, like the plants","body":"We optimise for the long view in the work and in careers — depth over churn, mastery over headcount."}],"roles":[{"title":"Project Engineer — EPC","location":"Site-based · Pan-India","type":"Full-time","body":"Own execution on site: civil, structures, DC/AC works, testing, and commissioning, on schedule and to spec."},{"title":"O&M Technician","location":"Delhi NCR","type":"Full-time","body":"Preventive and corrective maintenance, performance monitoring, and module-cleaning programmes across the operating fleet."}]},"faqs":[{"q":"How long does a typical project take from PO to commissioning?","a":"For rooftop projects under 1 MWp, the typical window is 8–14 weeks. EPC and utility-scale assets run 16–28 weeks. Approvals and DISCOM filings usually drive the critical path; we run those in parallel with engineering."},{"q":"Do you only work on new builds, or also take over existing plants?","a":"Both. We onboard existing assets into our O&M programme — whether built by another EPC or by an in-house team that no longer maintains it."},{"q":"What capacity range do you typically engineer for?","a":"Most rooftop projects sit between 100 kWp and 1.5 MWp. We have delivered EPC contracts beyond that and run O&M on plants from 50 kWp upward."},{"q":"How is the BOM specified, and can the client review component choices?","a":"Yes. Every BOM specifies the OEM and model number for modules, inverters, and key BoS. We share rationale on each line and welcome owner's-engineer review."}],"allProjects":[{"name":"Archies Limited","capacity":40,"location":"Delhi","system":"On-Grid","commissioned":"Jan 2017","sector":"Commercial"},{"name":"Mayur Public School","capacity":25,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2017","sector":"Institutional"},{"name":"Havells India Limited","capacity":632.4,"location":"Alwar","system":"On-Grid","commissioned":"Mar 2017","sector":"Industrial"},{"name":"Havells India Limited","capacity":10.08,"location":"Gurgaon","system":"On-Grid","commissioned":"Apr 2017","sector":"Industrial"},{"name":"Basant Projects Limited","capacity":40,"location":"Delhi","system":"On-Grid","commissioned":"Jun 2017","sector":"Commercial"},{"name":"Havells India Limited","capacity":6,"location":"Noida","system":"Off-Grid","commissioned":"Jun 2017","sector":"Industrial"},{"name":"Residential — Saket","capacity":5,"location":"Delhi","system":"On-Grid","commissioned":"Aug 2017","sector":"Residential"},{"name":"Mother Khazani Convent School","capacity":60,"location":"Delhi","system":"On-Grid","commissioned":"Sep 2017","sector":"Institutional"},{"name":"Havells India Limited","capacity":1000,"location":"Neemrana","system":"On-Grid","commissioned":"Oct 2017","sector":"Industrial"},{"name":"The Mann School","capacity":300,"location":"Delhi","system":"On-Grid","commissioned":"Jan 2018","sector":"Institutional"},{"name":"Aggarwal City Mall","capacity":100,"location":"Delhi","system":"On-Grid","commissioned":"Apr 2018","sector":"Commercial"},{"name":"Bon Ascent School","capacity":10,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"Shri Krishna Gaushala","capacity":100,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"L.M. Saraswati Bal Mandir","capacity":40,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"Saraswati Shishu Mandir","capacity":8,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"SSD Saraswati Bal Mandir","capacity":55,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"RK Saraswati Vidya Mandir","capacity":10,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"MCL Saraswati Bal Mandir Sr. Sec. School","capacity":12,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"ML Saraswati Bal Mandir","capacity":35,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2018","sector":"Institutional"},{"name":"Havells India Limited","capacity":2000,"location":"Ghiloth","system":"On-Grid","commissioned":"Apr 2019","sector":"Industrial"},{"name":"AVB Sr. Sec. School","capacity":30,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2019","sector":"Institutional"},{"name":"Gyan Mandir Public School","capacity":40,"location":"Delhi","system":"On-Grid","commissioned":"Nov 2019","sector":"Institutional"},{"name":"Don Bosco School","capacity":150,"location":"Delhi","system":"On-Grid","commissioned":"Dec 2019","sector":"Institutional"},{"name":"Bhai Vir Singh Sahitya Sadan","capacity":60,"location":"Delhi","system":"On-Grid","commissioned":"Jan 2020","sector":"Institutional"},{"name":"Mahabir Mandir Sabha","capacity":20,"location":"Delhi","system":"On-Grid","commissioned":"Jan 2020","sector":"Institutional"},{"name":"Shri Ram College of Commerce","capacity":425.75,"location":"Delhi","system":"On-Grid","commissioned":"May 2020","sector":"Institutional"},{"name":"Sri Guru Gobind Singh College of Commerce","capacity":803.02,"location":"Delhi","system":"On-Grid","commissioned":"Aug 2020","sector":"Institutional"},{"name":"Balvantray Mehta Vidya Bhawan","capacity":72.8,"location":"Delhi","system":"On-Grid","commissioned":"Aug 2020","sector":"Institutional"},{"name":"Hindu College","capacity":800,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2022","sector":"Institutional"},{"name":"Hansraj College","capacity":1000,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2022","sector":"Institutional"},{"name":"Miranda House","capacity":1000,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2022","sector":"Institutional"},{"name":"St. Stephen's College","capacity":500,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2022","sector":"Institutional"},{"name":"PGDAV College","capacity":450,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2022","sector":"Institutional"},{"name":"Jaswant Cold Storage","capacity":1200,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2022","sector":"Industrial"},{"name":"Model Town Residentials","capacity":38,"location":"Delhi","system":"On-Grid","commissioned":"Aug 2022","sector":"Residential"},{"name":"Challengers Automotive","capacity":16,"location":"Delhi","system":"On-Grid","commissioned":"Aug 2022","sector":"Commercial"},{"name":"Indraprastha Gas Limited","capacity":500,"location":"Delhi","system":"On-Grid","commissioned":"May 2022","sector":"Industrial"},{"name":"PEE PEE Enterprises","capacity":350,"location":"Delhi","system":"On-Grid","commissioned":"Nov 2024","sector":"Commercial"},{"name":"Elegent Mall Management","capacity":150,"location":"Delhi","system":"On-Grid","commissioned":"Nov 2025","sector":"Commercial"},{"name":"Hindustan Petroleum Corporation Limited (HPCL)","capacity":5600,"location":"Delhi","system":"On-Grid","commissioned":"Mar 2026","sector":"Industrial"},{"name":"Indraprastha Gas Limited","capacity":32,"location":"Delhi","system":"On-Grid","commissioned":"Sep 2025","sector":"Industrial"},{"name":"Unity One Mall Rohini","capacity":30,"location":"Delhi","system":"On-Grid","commissioned":"Jul 2026","sector":"Commercial"}]}$sunp$::jsonb)
